import json
from collections import Counter
shows = json.load(open('/home/user/EdFringeNow/data/normalized/shows.json'))
lh_nonfree_status = Counter(); sample = []
for s in shows:
    v = s.get('venueName','?')
    if 'Laughing Horse' not in v: continue
    sts = {p.get('ticketStatus') or p.get('status') for p in s.get('performances', [])}
    if not (sts & {'FREE_NON_TICKETED','FREE_TICKETED'}):
        for st in sts: lh_nonfree_status[st]+=1
        if len(sample) < 3:
            sample.append({'title': s.get('title'), 'venue': v, 'price': s.get('price') or s.get('prices') or {k:s[k] for k in s if 'price' in k.lower()}, 'statuses': sorted(x for x in sts if x)})
print("LH non-free shows statuses:", dict(lh_nonfree_status))
for x in sample: print(x)
EOF

